    expect(io.initialize).not.toHaveBeenCalled(); expect(io.creation).not.toHaveBeenCalled(); expect(io.calls).toEqual([]); expect(io.sent).toEqual([]); expect(io.remote).not.toHaveBeenCalled(); expect(f.cache.calls).toEqual([]);
