      expect(f.sessions.data.size).toBe(0); expect([...f.objects.values()].every(v => v.data.size === 0)).toBe(true);
      expect(host === 'session' ? f.sessions.calls.filter(v => v.startsWith('get:')).length : f.effects.filter(v => v.startsWith('object:')).length).toBe(1);
      expect(f.sessions.calls.filter(v => v.startsWith('put:'))).toEqual([]); expect(f.effects.filter(v => v.startsWith('store:'))).toEqual([]);
      f.effects.length = 0; f.sessions.calls.length = 0;
